import{_ as r,C as a,o as s,c as n,ag as t,E as i}from"./chunks/framework.yGqRar0R.js";const p=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),l={name:"guide/getting-started.md"};function d(c,e,h,u,m,g){const o=a("ComposeDownloads");return s(),n("div",null,[e[0]||(e[0]=t('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>SLS is built around <strong>Protocube</strong> (the controller) and one or more <strong>daemons</strong> (nodes that run Docker workloads). Install Protocube first, then add a daemon on each machine that should host game servers.</p><table tabindex="0"><thead><tr><th>Step</th><th>Guide</th></tr></thead><tbody><tr><td>1. Protocube</td><td><a href="./installing-protocube.html">Installing Protocube</a></td></tr><tr><td>2. Daemon (per node)</td><td><a href="./installing-daemon.html">Installing the daemon</a></td></tr></tbody></table><h2 id="host-requirements" tabindex="-1">Host requirements <a class="header-anchor" href="#host-requirements" aria-label="Permalink to &quot;Host requirements&quot;">​</a></h2><p>The <strong>daemon</strong> expects a full Linux environment on the host (Docker, cgroups, mount behavior used for game servers). If you use Windows, run Protocube and daemons inside <a href="https://learn.microsoft.com/en-us/windows/wsl/about" target="_blank" rel="noreferrer">Windows Subsystem for Linux (WSL)</a>, not only in a Windows-native shell.</p><ul><li><strong>Docker</strong> — Install Docker Engine (or a compatible runtime) on that Linux environment.</li><li><strong>WSL</strong> — If you use Docker Desktop on Windows, prefer <strong>Docker inside the same WSL distro</strong> you use for SLS, or expect networking and socket paths to need extra care. A dedicated Linux VM or bare metal avoids those edge cases.</li></ul><h2 id="images-and-releases" tabindex="-1">Images and releases <a class="header-anchor" href="#images-and-releases" aria-label="Permalink to &quot;Images and releases&quot;">​</a></h2><ul><li>Protocube: <code>ghcr.io/jessefaler/sls/protocube:latest</code></li><li>Daemon: <code>ghcr.io/jessefaler/sls/daemon:latest</code></li></ul><p>Binaries and changelog: <a href="https://github.com/jessefaler/SLS/releases" target="_blank" rel="noreferrer">SLS GitHub Releases</a>.</p><h2 id="official-docker-compose-files" tabindex="-1">Official Docker Compose files <a class="header-anchor" href="#official-docker-compose-files" aria-label="Permalink to &quot;Official Docker Compose files&quot;">​</a></h2><p>Use <strong>Protocube</strong> on the controller host, then <strong>Daemon (node)</strong> on each node (each in its own directory and <code>docker compose</code> project).</p>',11)),i(o,{which:"all"}),e[1]||(e[1]=t('<p>Sources: <a href="https://github.com/jessefaler/SLS/blob/main/protocube/docker-compose.yml" target="_blank" rel="noreferrer"><code>protocube/docker-compose.yml</code></a>, <a href="https://github.com/jessefaler/SLS/blob/main/daemon/docker-compose.yml" target="_blank" rel="noreferrer"><code>daemon/docker-compose.yml</code></a>.</p><h2 id="after-installation" tabindex="-1">After installation <a class="header-anchor" href="#after-installation" aria-label="Permalink to &quot;After installation&quot;">​</a></h2><ul><li>Author or import <a href="./blueprints/examples/">blueprints</a> and <a href="./software-configurations/introduction.html">software configurations</a>.</li><li>Stuck? See <a href="./troubleshooting/">Troubleshooting</a> or ask on <a href="https://discord.gg/BrH8GtyGSh" target="_blank" rel="noreferrer">Discord</a>.</li></ul>',3))])}const b=r(l,[["render",d]]);export{p as __pageData,b as default};
